from collections import Counter


def is_anagram(a, b):
    return Counter(a.lower()) == Counter(b.lower())


def merge_counts(*counters):
    total = Counter()
    for c in counters:
        total += c
    return total


def top_n_words(texts, n):
    total = Counter()
    for text in texts:
        total += Counter(text.lower().split())
    return [word for word, _ in total.most_common(n)]
